{"packet_id":"D067-03","doc_id":"D067","jurisdiction":"NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"New Jersey Anti-Eviction Act grounds for eviction","requirement":"A landlord may evict only for an enumerated statutory ground — such as nonpayment, disorderly conduct, damage, lease breach, health/safety removal, retirement from the market, conversion, employment or drug conviction — and must serve the notice the ground requires.","key_value":"Notice to Quit 3 days to 3 years by ground","coverage_conditions":"Most residential rentals: single-family homes, mobile homes and park land, apartment buildings, complexes, rooming and boarding homes; owner-occupied premises with two or fewer rental units and certain trust-held units excepted.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"owner-occupied premises with two or fewer rental units","unit_limit":3},{"type":"other","text":"unit held in trust for a developmentally disabled immediate family member who permanently occupies it"}],"per_tenancy":"Only the enumerated statutory grounds permit eviction; the required notice period varies by ground.","coverage_quotes":["The Anti-Eviction Act applies to most residential rental properties including single-family homes, mobile homes and land in a mobile home park, apartment buildings, and complexes.","This law may not apply to two - or three-unit owner-occupied premises with two (2) or fewer rental units.","Additionally, this law does not apply to a unit held in trust on behalf of a member of the immediate family, if that family member is developmentally disabled, and permanently occupies the dwelling unit."]},"exemptions":"Owner-occupied two- or three-unit premises with two or fewer rental units; hotel, motel and transient guests; a unit held in trust for a developmentally disabled immediate family member who permanently occupies it.","penalty":"For an illegal-occupancy eviction, relocation assistance equal to six times the monthly rent; unpaid relocation funds accrue 18% annual interest and are a lien on the property.","effective_date":null,"valid_through":null,"citation":"N.J.S.A. 2A:18-61.1","quoted_span":"A Notice to Quit must be served on the tenant at least 18 months prior to filing the suit for eviction. No legal action may be taken until the lease expires","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-03","doc_id":"D067","jurisdiction":"NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"New Jersey prohibition on self-help evictions and lockouts","requirement":"A landlord may not remove a tenant, padlock the unit, shut off utilities or otherwise block entry without a court judgment; only a court officer may physically evict after a warrant for removal is issued.","key_value":null,"coverage_conditions":"Applies to tenants of dwelling units in New Jersey under any circumstances.","applicability":{"conditions":[],"per_tenancy":"Applies when a landlord removes a tenant or blocks entry without a court order.","coverage_quotes":[]},"exemptions":null,"penalty":"Landlord may be charged with disorderly conduct and is liable for damages, court costs and reasonable attorney fees; the court may award possession of the unit.","effective_date":null,"valid_through":null,"citation":"N.J.S.A. 2A:39-1","quoted_span":"A landlord or their agent may not padlock, disconnect utilities or otherwise block entry to a rental premise while the tenant still lives there.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
